export const getDeleteSharedTokenItemsItemIdUrl = (token: string,
    itemId: string,
    params?: DeleteSharedTokenItemsItemIdParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/shared/${token}/items/${itemId}?${stringifiedParams}` : `/shared/${token}/items/${itemId}`
}

